/* From Uiverse.io by Shoh2008 - Tags: input */
.__UIV_SCOPE__ .input {
  max-width: 190px;
  width: 40px;
  height: 40px;
  outline: none;
  margin: 5px;
  transition: .5s;
  border: none;
  border-radius: 10px;
  padding: 10px;
  text-align: center;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  transform: rotate(90deg);
}

.__UIV_SCOPE__ input:focus {
  width: 150px;
  transform: rotate(0);
}
